@extends('layouts.app')@section('title','Chat')@section('content')<div class="pagehead"><div><h1>Chat {{ auth()->user()->role==='buyer'?'Citra Susu':$buyer->name }}</h1><div class="sub">Pesan tersimpan dan dapat dilihat kembali.</div></div><a class="btn light" href="{{ route('chat') }}">Kembali</a></div><div class="panel"><div id="chatlog" class="chatlog">@foreach($messages as $m)<div class="message {{ $m->sender_id===auth()->id()?'mine':'' }}"><b>{{ $m->sender }}</b><div>{{ $m->body }}</div><small class="muted">{{ \Carbon\Carbon::parse($m->created_at)->format('d/m H:i') }} · {{ $m->read_at?'Dibaca':'Terkirim' }}</small></div>@endforeach</div><form method="POST" action="{{ route('chat.send',$c->id) }}" style="display:flex;gap:9px;margin-top:12px">@csrf<input name="body" maxlength="2000" placeholder="Tulis pesan..." required style="flex:1;border:1px solid #ddd;border-radius:12px;padding:12px"><button class="btn">Kirim</button></form></div>@endsection
@push('scripts')<script>
let lastId={{ $messages->last()->id??0 }};const box=document.getElementById('chatlog');box.scrollTop=box.scrollHeight;
setInterval(async()=>{try{const r=await fetch(@json(route('chat.poll',$c->id))+'?after='+lastId,{headers:{'Accept':'application/json'}});if(!r.ok)return;const rows=await r.json();rows.forEach(m=>{lastId=m.id;const el=document.createElement('div');el.className='message '+(m.sender_id=== {{ auth()->id() }}?'mine':'');const b=document.createElement('b');b.textContent=m.sender;const p=document.createElement('div');p.textContent=m.body;const sm=document.createElement('small');sm.className='muted';sm.textContent=m.created_at;el.append(b,p,sm);box.append(el)});box.scrollTop=box.scrollHeight}catch(e){}},3000);
</script>@endpush